    """raw_spk: neurons x frames
        accum_pos: accumulated position, should be increasement
        corridorLen: length of corrdior
        new_shape: [0]: trials number. [1]: bins for each corridor, if[1]==0 then bins=corridorLen
    """
    if len(new_shape)==2:
